//! Compares oxlight with the reference Shiki output.
//!
//! The fixtures are generated by `scripts/fixtures/generate.mjs`.

use std::fs;
use std::path::{Path, PathBuf};

use oxlight::{HighlightOptions, Highlighter};

const THEMES: &[&str] = &[
    "github-dark",
    "github-light",
    "dracula",
    "catppuccin-mocha",
    "one-dark-pro",
    "vitesse-light",
    "nord",
    "min-light",
];

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn highlighter() -> Highlighter {
    let mut h = Highlighter::new();
    let mut entries: Vec<_> = fs::read_dir(fixtures().join("langs"))
        .unwrap()
        .map(|e| e.unwrap().path())
        .collect();
    entries.sort();
    for path in entries {
        h.load_language_json(&fs::read_to_string(&path).unwrap())
            .unwrap();
    }
    for theme in THEMES {
        let path = fixtures().join("themes").join(format!("{theme}.json"));
        h.load_theme_json(&fs::read_to_string(path).unwrap())
            .unwrap();
    }
    h
}

fn samples() -> Vec<(String, String, String)> {
    let mut out = Vec::new();
    let mut entries: Vec<_> = fs::read_dir(fixtures().join("samples"))
        .unwrap()
        .map(|e| e.unwrap().path())
        .collect();
    entries.sort();
    for path in entries {
        let file = path.file_name().unwrap().to_string_lossy().to_string();
        let mut parts = file.split('.');
        let base = parts.next().unwrap().to_string();
        let lang = parts.next().unwrap().to_string();
        out.push((base, lang, fs::read_to_string(&path).unwrap()));
    }
    out
}

/// Line-level diff, enough to locate a mismatch.
fn first_difference(expected: &str, actual: &str) -> String {
    for (i, (e, a)) in expected.lines().zip(actual.lines()).enumerate() {
        if e != a {
            return format!("line {}:\n  expected: {e}\n  actual:   {a}", i + 1);
        }
    }
    format!(
        "line count differs: expected {}, actual {}",
        expected.lines().count(),
        actual.lines().count()
    )
}

fn check(cases: Vec<(String, String, String)>) {
    let h = highlighter();
    let mut failures = Vec::new();
    let mut total = 0;
    for (name, options, code) in cases {
        let _ = &options;
        let expected =
            fs::read_to_string(fixtures().join("expected").join(format!("{name}.html"))).unwrap();
        let opts = if name.ends_with("__dual") {
            HighlightOptions::with_themes(
                name.split("__").next().unwrap().split('.').nth(1).unwrap(),
                [("light", "github-light"), ("dark", "github-dark")],
            )
        } else {
            let (sample, theme) = name.split_once("__").unwrap();
            HighlightOptions::new(sample.split('.').nth(1).unwrap(), theme)
        };
        total += 1;
        let actual = h.code_to_html(&code, &opts).unwrap();
        if actual != expected {
            failures.push(format!("{name}: {}", first_difference(&expected, &actual)));
        }
    }
    if !failures.is_empty() {
        panic!(
            "{} of {total} outputs differ from Shiki:\n\n{}",
            failures.len(),
            failures.join("\n\n")
        );
    }
}

#[test]
fn single_theme_matches_shiki() {
    let mut cases = Vec::new();
    for (base, lang, code) in samples() {
        for theme in THEMES {
            cases.push((
                format!("{base}.{lang}__{theme}"),
                String::new(),
                code.clone(),
            ));
        }
    }
    check(cases);
}

#[test]
fn dual_themes_match_shiki() {
    let cases = samples()
        .into_iter()
        .map(|(base, lang, code)| (format!("{base}.{lang}__dual"), String::new(), code))
        .collect();
    check(cases);
}
